// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Owned} from "../src/Owned.sol";

contract InvMutTest is Test {
    Owned c;
    function setUp() public { c = new Owned(); }
    function testFuzz_property(address caller, address newOwner) public {
        vm.assume(caller != address(this) && caller != address(0));
        address prevOwner = c.owner();
        vm.prank(caller);
        (bool success,) = address(c).call(abi.encodeWithSignature("setOwner(address)", newOwner));
        address expected = (caller == address(uint160(uint256(keccak256(abi.encodePacked(address(c), bytes32(uint256(1)))))))) ? newOwner : prevOwner;
        assertEq(c.owner(), expected);
    }
}
